struct Models {
    std::shared_ptr<slint::VectorModel<TaskRowDto>> tasks = std::make_shared<slint::VectorModel<TaskRowDto>>();
    std::shared_ptr<slint::VectorModel<PieceDto>> detailPieces = std::make_shared<slint::VectorModel<PieceDto>>();
    std::shared_ptr<slint::VectorModel<ConnectionDto>> detailConnections = std::make_shared<slint::VectorModel<ConnectionDto>>();
    std::shared_ptr<slint::VectorModel<FileRowDto>> detailFiles = std::make_shared<slint::VectorModel<FileRowDto>>();
    std::shared_ptr<slint::VectorModel<AlertDto>> alerts = std::make_shared<slint::VectorModel<AlertDto>>();
    std::shared_ptr<slint::VectorModel<QualityRowDto>> addQualities = std::make_shared<slint::VectorModel<QualityRowDto>>();
    std::shared_ptr<slint::VectorModel<SubtitleRowDto>> addSubtitles = std::make_shared<slint::VectorModel<SubtitleRowDto>>();
    std::shared_ptr<slint::VectorModel<PlaylistRowDto>> addPlaylist = std::make_shared<slint::VectorModel<PlaylistRowDto>>();
    std::shared_ptr<slint::VectorModel<ChoiceDialogDto>> choices = std::make_shared<slint::VectorModel<ChoiceDialogDto>>();
    std::shared_ptr<slint::VectorModel<SettingRowDto>> settingsRows = std::make_shared<slint::VectorModel<SettingRowDto>>();
    std::shared_ptr<slint::VectorModel<LinkRowDto>> addLinks = std::make_shared<slint::VectorModel<LinkRowDto>>();
    std::shared_ptr<slint::VectorModel<DeviceRowDto>> deviceRows = std::make_shared<slint::VectorModel<DeviceRowDto>>();
    std::shared_ptr<slint::VectorModel<TorrentFileRowDto>> addTorrentFiles = std::make_shared<slint::VectorModel<TorrentFileRowDto>>();
};

inline void bind_models(const Core &core, const Models &models) {
    core.set_tasks(models.tasks);
    core.set_detailPieces(models.detailPieces);
    core.set_detailConnections(models.detailConnections);
    core.set_detailFiles(models.detailFiles);
    core.set_alerts(models.alerts);
    core.set_addQualities(models.addQualities);
    core.set_addSubtitles(models.addSubtitles);
    core.set_addPlaylist(models.addPlaylist);
    core.set_choices(models.choices);
    core.set_settingsRows(models.settingsRows);
    core.set_addLinks(models.addLinks);
    core.set_deviceRows(models.deviceRows);
    core.set_addTorrentFiles(models.addTorrentFiles);
}

inline bool apply_channel(const Core &core, Models &models, int channel, const fj::Json &j) {
    switch (channel) {
        case 1: core.set_shell(parse_ShellDto(j)); return true;
        case 2: core.set_chrome(parse_ChromeDto(j)); return true;
        case 3: core.set_status(parse_StatusDto(j)); return true;
        case 4: fj::apply_rows<TaskRowDto>(*models.tasks, j, parse_TaskRowDto); return true;
        case 6: core.set_details(parse_DetailsDto(j)); return true;
        case 7: fj::apply_rows<PieceDto>(*models.detailPieces, j, parse_PieceDto); return true;
        case 8: fj::apply_rows<ConnectionDto>(*models.detailConnections, j, parse_ConnectionDto); return true;
        case 9: fj::apply_rows<FileRowDto>(*models.detailFiles, j, parse_FileRowDto); return true;
        case 10: fj::apply_rows<AlertDto>(*models.alerts, j, parse_AlertDto); return true;
        case 11: core.set_add(parse_AddDto(j)); return true;
        case 12: core.set_addMedia(parse_AddMediaDto(j)); return true;
        case 13: fj::apply_rows<QualityRowDto>(*models.addQualities, j, parse_QualityRowDto); return true;
        case 14: fj::apply_rows<SubtitleRowDto>(*models.addSubtitles, j, parse_SubtitleRowDto); return true;
        case 15: fj::apply_rows<PlaylistRowDto>(*models.addPlaylist, j, parse_PlaylistRowDto); return true;
        case 16: core.set_clipPicker(parse_ClipPickerDto(j)); return true;
        case 17: fj::apply_rows<ChoiceDialogDto>(*models.choices, j, parse_ChoiceDialogDto); return true;
        case 18: core.set_settingsNav(parse_SettingsNavDto(j)); return true;
        case 19: fj::apply_rows<SettingRowDto>(*models.settingsRows, j, parse_SettingRowDto); return true;
        case 20: core.set_updateDialog(parse_UpdateDialogDto(j)); return true;
        case 21: fj::apply_rows<LinkRowDto>(*models.addLinks, j, parse_LinkRowDto); return true;
        case 22: core.set_deviceSheet(parse_DeviceSheetDto(j)); return true;
        case 23: fj::apply_rows<DeviceRowDto>(*models.deviceRows, j, parse_DeviceRowDto); return true;
        case 24: core.set_devicePairing(parse_DevicePairingDto(j)); return true;
        case 25: core.set_addTorrent(parse_AddTorrentDto(j)); return true;
        case 26: fj::apply_rows<TorrentFileRowDto>(*models.addTorrentFiles, j, parse_TorrentFileRowDto); return true;
        default: return false;
    }
}

inline std::vector<EffectDto> parse_effects_queue(const fj::Json &j) {
    std::vector<EffectDto> items;
    for (const auto &item : j.items) items.push_back(parse_EffectDto(item));
    return items;
}

